import type { PrivateKeyAccount, HDAccount } from 'viem/accounts';
export type WalletSecret = { kind: 'mnemonic' | 'privateKey'; value: string };
export type VaultEnvelope = { version: 1; kdf: 'pbkdf2-sha256'; iterations: number; salt: string; nonce: string; ciphertext: string };
export function randomBytes(length: number): Uint8Array;
export function createRecoveryPhrase(): string;
export function normalizeSecret(input: string, kind: WalletSecret['kind']): WalletSecret;
export function accountFromSecret(secret: WalletSecret): PrivateKeyAccount | HDAccount;
export function validatePassword(password: string): void;
export function encryptSecret(secret: WalletSecret, password: string): Promise<VaultEnvelope>;
export function decryptSecret(envelope: VaultEnvelope, password: string): Promise<WalletSecret>;
export function validateEnvelope(envelope: unknown): VaultEnvelope;
export type RecoveryPrompt = { index: number; choices: string[] };
export function recoveryChallenge(phrase: string): RecoveryPrompt[];
